<script>
import opportunityLayout from '@/Layouts/opportunityLayout';
export default { layout: opportunityLayout };
</script>
<script setup>
import { computed, ref } from 'vue';
import { Link, router, usePage, useForm } from '@inertiajs/vue3';
import { ArrowUpRight, Bookmark, Check, Copy, Download } from '@lucide/vue';
import CompanyLogo from '@/Components/Ui/CompanyLogo.vue';
import RoleCard from '@/Components/Internship/RoleCard.vue';
const props = defineProps({ internship: { type: Object, required: true }, related: { type: [Object, Array], default: () => ({ data: [] }) } });
const relatedListings = computed(() => Array.isArray(props.related) ? props.related : props.related?.data || []);
const page = usePage();
const user = computed(() => page.props.auth?.user);
const candidate = computed(() => user.value?.is_candidate || user.value?.userable_type === 'student');
const ownsIt = computed(() => user.value?.is_admin || (props.internship.origin === 'native' && user.value?.userable_type === 'company' && user.value?.userable_id === props.internship.company?.id));
const external = computed(() => props.internship.application_mode === 'external');
const copied = ref(false);
const confirming = ref(false);
const notes = ref('');
const tracking = ref(false);
const reportOpen = ref(false);
const report = useForm({ reason: 'incorrect', details: '' });
const submitReport = () => report.post(`/opportunities/${props.internship.id}/report`, { preserveScroll: true, onSuccess: () => { report.reset(); reportOpen.value = false; } });
const deadline = computed(() => props.internship.expires_at ? new Intl.DateTimeFormat('en-GB', { dateStyle: 'long', timeStyle: 'short', timeZone: 'Africa/Tunis' }).format(new Date(props.internship.expires_at)) + ' (Tunisia time)' : props.internship.closing_at || 'No deadline listed');
const workTypes = { remote: 'Remote', hybrid: 'Hybrid', onsite: 'Onsite', unknown: 'Not specified' };
const payLabel = computed(() => {
    const pay = props.internship.pay;
    if (!pay) return props.internship.compensation_status === 'unpaid' ? 'Unpaid' : 'Compensation not specified';
    const minimum = pay.min ?? pay.amount;
    const min = minimum == null ? null : Math.round(Number(minimum));
    const max = pay.max == null ? null : Math.round(Number(pay.max));
    const amount = min != null && max != null && min !== max ? `${min}–${max}` : min ?? max;
    return `${amount ?? ''} ${pay.currency || '(currency not specified)'}${pay.unit ? ` / ${pay.unit}` : ''}`;
});
const eligibility = computed(() => props.internship.remote_eligibility === 'eligible' ? 'The source explicitly permits work from Tunisia.' : props.internship.remote_eligibility === 'restricted' ? 'The source lists location restrictions. Work from Tunisia is not confirmed as eligible.' : 'Eligibility to work from Tunisia is unknown. Confirm it with the employer before applying.');
const evidenceLabel = (value) => ({ yes: 'Stated by the employer or source', no: 'Not offered according to the source', unknown: 'Not specified' }[value] || 'Not specified');
const save = () => router.post(`/like/${props.internship.id}`, {}, { preserveScroll: true });
const track = () => {
    tracking.value = true;
    router.post(`/opportunities/${props.internship.id}/track`, { candidate_notes: notes.value }, { preserveScroll: true, onFinish: () => { tracking.value = false; confirming.value = false; } });
};
const copy = async () => {
    try { await navigator.clipboard.writeText(props.internship.public_url || window.location.href); copied.value = true; }
    catch { copied.value = false; }
};
const remove = () => {
    if (window.confirm('Remove this opportunity from public discovery? Existing application history will be retained.')) router.delete(`/internships/${props.internship.id}`);
};
</script>
<template>
    <div class="public-container pt-7 pb-16">
        <nav aria-label="Breadcrumb" class="text-sm text-slate-600 mb-6 flex flex-wrap gap-2"><Link href="/opportunities" class="hover:text-blue-700">Opportunities</Link><span aria-hidden="true">/</span><Link :href="`/opportunities/${internship.kind === 'job' ? 'jobs' : 'internships'}`">{{ internship.kind === 'job' ? 'Jobs' : 'Internships' }}</Link><span aria-hidden="true">/</span><span aria-current="page" class="font-semibold text-navy">{{ internship.title }}</span></nav>
        <div class="grid lg:grid-cols-[minmax(0,1fr)_340px] gap-6 items-start">
            <div class="space-y-5">
                <header class="bg-white border border-line rounded-2xl p-6 sm:p-8"><div class="flex items-start gap-4"><CompanyLogo class="w-14 h-14 shrink-0 rounded-2xl text-xl" :name="internship.company?.name || 'Company'" /><div><p class="text-xs font-bold uppercase tracking-widest text-blue-700 mb-2">{{ internship.kind === 'job' ? 'Job opportunity' : 'Internship opportunity' }}</p><h1 class="font-display text-3xl sm:text-4xl font-semibold leading-tight">{{ internship.title }}</h1><p class="mt-3 text-slate-600">{{ internship.company?.name }}<span v-if="internship.field?.name"> · {{ internship.field.name }}</span></p></div></div><div class="flex flex-wrap gap-2 mt-6 text-sm"><span class="rounded-lg bg-paper-2 px-3 py-2">{{ internship.location_label || internship.city?.name || 'Location not specified' }}</span><span v-if="internship.work_type" class="rounded-lg bg-paper-2 px-3 py-2">{{ workTypes[internship.work_type] || internship.work_type }}</span><span v-if="internship.seniority" class="rounded-lg bg-paper-2 px-3 py-2 capitalize">{{ internship.seniority }}</span><span v-if="internship.kind !== 'job' && internship.duration_weeks" class="rounded-lg bg-paper-2 px-3 py-2">{{ internship.duration_weeks }} weeks</span><span v-if="internship.program_type" class="rounded-lg bg-paper-2 px-3 py-2 uppercase">{{ internship.program_type }}</span><span v-for="type in internship.employment_types || []" :key="type" class="rounded-lg bg-paper-2 px-3 py-2">{{ type.replaceAll('_', ' ').toLowerCase() }}</span></div><p v-if="!internship.is_open" class="mt-5 rounded-xl bg-amber-50 border border-amber-200 text-amber-900 p-4">This opportunity is closed. Applications are no longer available here. Your saved listing and application history remain accessible.</p><a v-if="internship.is_open" href="#application-options" class="cta cta-primary w-full mt-5 lg:hidden">View application options</a></header>
                <section class="bg-white border border-line rounded-2xl p-6 sm:p-8"><h2 class="font-display text-xl font-semibold mb-5">About this opportunity</h2><div :lang="internship.language || undefined" dir="auto" class="whitespace-pre-line text-base text-slate-700 leading-8 break-words">{{ internship.description }}</div><div v-if="internship.skills?.length" class="mt-8 border-t border-line pt-6"><h2 class="font-display text-lg font-semibold mb-4">Skills and expertise</h2><div class="flex flex-wrap gap-2"><span v-for="skill in internship.skills" :key="skill" class="bg-blue-50 text-blue-700 rounded-lg px-3 py-2 text-sm font-semibold">{{ skill }}</span></div></div><div v-if="internship.attachments?.length" class="mt-8 border-t border-line pt-6"><h2 class="font-display text-lg font-semibold mb-4">Opportunity attachments</h2><a v-for="attachment in internship.attachments" :key="attachment.url" :href="attachment.url" target="_blank" rel="noopener noreferrer" class="flex items-center gap-2 py-2 text-blue-700 break-all"><Download :size="18" />{{ attachment.name }}</a></div></section>
                <section class="bg-white border border-line rounded-2xl p-6 sm:p-8"><h2 class="font-display text-xl font-semibold mb-5">Location and eligibility</h2><p v-if="internship.work_type === 'remote'" class="text-slate-700 leading-7 mb-5">{{ eligibility }}</p><dl class="space-y-4 text-sm"><div v-if="internship.locations?.length"><dt class="font-semibold">Work locations</dt><dd class="text-slate-600 mt-1"><ul><li v-for="(location, index) in internship.locations" :key="index">{{ location.location || [location.city, location.country_code].filter(Boolean).join(', ') }}</li></ul></dd></div><div v-if="internship.start_date"><dt class="font-semibold">Start date</dt><dd class="text-slate-600 mt-1">{{ internship.start_date }}</dd></div><div v-if="internship.remote_scope"><dt class="font-semibold">Remote scope stated by source</dt><dd class="text-slate-600 mt-1">{{ internship.remote_scope }}</dd></div><div v-if="internship.eligible_countries?.length"><dt class="font-semibold">Eligible applicant countries</dt><dd class="text-slate-600 mt-1">{{ internship.eligible_countries.join(', ') }}</dd></div><div v-if="internship.excluded_countries?.length"><dt class="font-semibold">Excluded applicant countries</dt><dd class="text-slate-600 mt-1">{{ internship.excluded_countries.join(', ') }}</dd></div><div><dt class="font-semibold">Relocation assistance</dt><dd class="text-slate-600 mt-1">{{ evidenceLabel(internship.relocation) }}</dd></div><div><dt class="font-semibold">Visa sponsorship</dt><dd class="text-slate-600 mt-1">{{ evidenceLabel(internship.visa_sponsorship) }}</dd></div></dl><p class="text-xs text-slate-500 leading-6 mt-5">Relocation support does not automatically include visa sponsorship. Unknown information has not been confirmed by the source.</p></section>
                <section class="bg-white border border-line rounded-2xl p-6 sm:p-8"><h2 class="font-display text-xl font-semibold mb-5">Source and dates</h2><dl class="grid sm:grid-cols-2 gap-5 text-sm"><div><dt class="font-semibold">{{ internship.posted_at ? 'Originally posted' : 'Added to Nextward' }}</dt><dd class="mt-1 text-slate-600">{{ internship.posted_label || internship.created_at || 'Date unavailable' }}</dd></div><div><dt class="font-semibold">Application deadline</dt><dd class="mt-1 text-slate-600">{{ deadline }}</dd></div><div><dt class="font-semibold">Source</dt><dd class="mt-1 text-slate-600"><a v-if="internship.source_url" :href="internship.source_url" target="_blank" rel="noopener noreferrer" class="text-blue-700 underline">{{ internship.source_name || 'Original listing' }}</a><span v-else>Posted by the employer on Nextward</span></dd></div><div v-if="internship.origin === 'imported'"><dt class="font-semibold">Last successful source check</dt><dd class="mt-1 text-slate-600">{{ internship.last_verified_label || 'Not yet verified' }}</dd></div></dl><p v-if="internship.origin === 'imported'" class="mt-5 text-xs text-slate-500 leading-6">A source check confirms the information available at that time. It is not an endorsement of the employer or a guarantee that the role remains available.</p></section>
            </div>
            <aside class="space-y-5 lg:sticky lg:top-24">
                <section id="application-options" class="bg-white border border-line rounded-2xl p-6 scroll-mt-24"><p class="font-display text-xl font-semibold leading-snug">{{ payLabel }}</p><p class="text-xs text-slate-500 mt-2 mb-6">As supplied by the employer or source.</p>
                    <template v-if="ownsIt"><Link :href="`/internships/${internship.id}/edit`" class="cta cta-primary w-full">Edit opportunity</Link><Link v-if="!external" :href="`/internships/${internship.id}/applications`" class="cta cta-secondary w-full mt-3">Review applicants</Link><button type="button" class="text-red-600 text-sm font-semibold mt-4 w-full" @click="remove">Remove opportunity</button></template>
                    <template v-else>
                        <Link v-if="internship.application" :href="`/applications/${internship.application.id}`" class="flex items-center justify-center gap-2 p-3 rounded-xl bg-green-50 text-green-800 font-semibold mb-4"><Check :size="18" />View your {{ external ? 'application tracking' : 'application' }}</Link>
                        <template v-if="internship.is_open">
                            <template v-if="external && internship.application_url"><a :href="internship.application_url" target="_blank" rel="noopener noreferrer" class="cta cta-primary w-full">Apply on source website<ArrowUpRight :size="18" /></a><p class="text-xs text-slate-500 leading-6 mt-3">This opens the employer or source application page. Following the link does not submit an application or share your CV.</p><button v-if="candidate && !internship.application" type="button" class="cta cta-secondary w-full mt-4" @click="confirming = !confirming">I applied</button><form v-if="confirming" class="mt-4 border-t border-line pt-4" @submit.prevent="track"><label class="block text-sm font-semibold">Private notes (optional)<textarea v-model="notes" maxlength="5000" rows="3" class="w-full border-line rounded-lg mt-2" /></label><p class="text-xs text-slate-500 mt-2">Confirm only after you have sent your application on the other website. This record is private and candidate-reported.</p><button type="submit" :disabled="tracking" class="cta cta-primary w-full mt-3">{{ tracking ? 'Saving…' : 'Confirm I applied' }}</button></form><Link v-if="!user" href="/login" class="block mt-4 text-sm font-semibold text-blue-700">Log in to save or track this opportunity</Link></template>
                            <Link v-else-if="candidate && !internship.application" :href="`/internships/${internship.id}/apply`" class="cta cta-primary w-full">Apply on Nextward</Link><Link v-else-if="!user" href="/login" class="cta cta-primary w-full">Log in to apply on Nextward</Link><p v-else-if="!candidate" class="text-sm text-slate-600">Use a candidate account to apply.</p>
                        </template>
                        <div v-else class="rounded-xl bg-paper-2 p-4 text-sm text-slate-600">Applications are closed.<Link href="/opportunities" class="block text-blue-700 font-semibold mt-3">Browse open opportunities</Link></div>
                    </template>
                    <button v-if="candidate" type="button" class="cta cta-secondary w-full mt-4" :aria-pressed="!!internship.liked" @click="save"><Bookmark :size="17" />{{ internship.liked ? 'Saved opportunity' : 'Save opportunity' }}</button><button type="button" class="inline-flex justify-center gap-2 text-sm text-slate-600 mt-4 w-full" @click="copy"><Copy :size="16" />{{ copied ? 'Link copied' : 'Copy opportunity link' }}</button>
                </section>
                <section class="bg-white border border-line rounded-2xl p-6"><h2 class="font-display text-xl font-semibold">{{ internship.company?.name }}</h2><p v-if="internship.company?.city?.name" class="text-sm text-slate-600 mt-3">{{ internship.company.city.name }}</p><a v-if="internship.company?.website" :href="internship.company.website" target="_blank" rel="noopener noreferrer" class="inline-flex gap-2 text-sm font-semibold text-blue-700 mt-5">Visit employer website<ArrowUpRight :size="17" /></a><p v-if="!internship.company?.user_id" class="mt-4 text-xs text-slate-500 leading-6">This employer does not have a managed account on Nextward.</p></section>
                <section class="rounded-2xl border border-line p-5"><p class="text-sm text-slate-600">A broken link, inaccurate details, or a suspicious opportunity?</p><button type="button" class="inline-block text-sm text-blue-700 font-semibold mt-3" @click="reportOpen = !reportOpen">Report an issue</button><form v-if="reportOpen" class="mt-4 space-y-3" @submit.prevent="submitReport"><label class="block text-sm font-semibold">Issue<select v-model="report.reason" class="w-full rounded-lg border-line mt-2"><option value="closed">Already closed</option><option value="broken_link">Broken application link</option><option value="incorrect">Incorrect information</option><option value="scam">Suspicious listing</option><option value="duplicate">Duplicate</option><option value="other">Other</option></select></label><label class="block text-sm font-semibold">Details (optional)<textarea v-model="report.details" rows="3" maxlength="2000" class="w-full rounded-lg border-line mt-2" /></label><p v-for="(error, key) in report.errors" :key="key" class="text-xs text-red-600">{{ error }}</p><button type="submit" :disabled="report.processing" class="cta cta-primary w-full">Send report</button></form></section>
            </aside>
        </div>
        <section v-if="relatedListings.length" class="mt-14"><h2 class="font-display text-2xl font-semibold mb-6">More opportunities to explore</h2><div class="grid lg:grid-cols-2 gap-4"><RoleCard v-for="opportunity in relatedListings" :key="opportunity.id" :internship="opportunity" /></div></section>
    </div>
</template>
